From 1f350f4bf88d1fbb67bf30d17fd74231417a5fa2 Mon Sep 17 00:00:00 2001
From: Razvan Crainea <razvan@opensips.org>
Date: Thu, 30 Aug 2018 18:26:29 +0300
Subject: [PATCH] dialog: fix unset_dlg_profile() linkers deletion

This commit fixes the following bugs introduced in commit 00cddf7:
1. when it was called, it was removing all the linkers of a dialog
2. it was not removing the actual linker it was called for, causing
constant increase in size for that specific profile (and leak)
3. when temporary copying the profiles list, the values were not copied,
thus they might have dissapeared when the actual cleanup was done.

Many thanks to Jonathan Hulme for reporting the issue and providing
testing framework for detecting the bug and testing the fix!

diff --git a/modules/dialog/dlg_profile.c b/modules/dialog/dlg_profile.c
index e7e76f8ae..50a6dbad4 100644
--- a/modules/dialog/dlg_profile.c
+++ b/modules/dialog/dlg_profile.c
@@ -572,40 +572,45 @@ void destroy_dlg_profiles(void)
 }

 /* array of temporary copies of the dialog profile linkers */
-static struct dlg_profile_link *tmp_linkers_arr, *tmp_linkers;
-static int n_tmp_linkers, tmp_linkers_size;
+static struct dlg_profile_link *tmp_linkers;

 static int init_tmp_linkers(struct dlg_cell *dlg)
 {
 	struct dlg_profile_link *l;
-	int i;
+	int i, len;
+	char *p;

-	for (l = dlg->profile_links, i = 0; l; l = l->next, i++) {
-		if (i == n_tmp_linkers) {
-			if (n_tmp_linkers == 0) {
-				tmp_linkers_size = sizeof *l;
-				n_tmp_linkers = 1;
-			} else {
-				tmp_linkers_size *= 2;
-				n_tmp_linkers *= 2;
-			}
-			tmp_linkers_arr = pkg_realloc(tmp_linkers_arr, tmp_linkers_size);
-			if (!tmp_linkers_arr) {
-				LM_ERR("No more pkg memory\n");
-				tmp_linkers = NULL;
-				return -1;
-			}
-		}
+	len = 0;
+
+	/* count the size we need to alocate */
+	for (l = dlg->profile_links, i = 0; l; l = l->next) {
+		len += sizeof *l;
+		if (l->profile->has_value)
+			len += l->value.len;
+		i++;
+	}

-		memcpy(&tmp_linkers_arr[i], l, sizeof *l);
+	tmp_linkers = pkg_malloc(len);
+	if (!tmp_linkers) {
+		LM_ERR("No more pkg memory\n");
+		return -1;
+	}
+
+	p = (char *)(tmp_linkers + i);
+	for (l = dlg->profile_links, i = 0; l; l = l->next, i++) {
+		memcpy(&tmp_linkers[i], l, sizeof *l);
 		if (i != 0)
-			tmp_linkers_arr[i-1].next = &tmp_linkers_arr[i];
+			tmp_linkers[i-1].next = &tmp_linkers[i];
+		if (l->profile->has_value) {
+			tmp_linkers[i].value.s = p;
+			memcpy(p, l->value.s, l->value.len);
+			p += l->value.len;
+		}
 	}

-	if (dlg->profile_links) {
-		tmp_linkers_arr[i-1].next = NULL;
-		tmp_linkers = &tmp_linkers_arr[0];
-	} else
+	if (dlg->profile_links)
+		tmp_linkers[i-1].next = NULL;
+	else
 		tmp_linkers = NULL;

 	return 0;
@@ -641,84 +646,97 @@ void destroy_linkers(struct dlg_cell *dlg, char is_replicated)
 	dlg_unlock_dlg(dlg);
 }

